"import urllib.request

endpoints = ['/', '/docs', '/antenna', '/health', '/health_manager', '/screen', '/backup', '/report', '/logs']
for ep in endpoints:
    url = f'http://192.168.12.193:8088{ep}'
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Test'})
        with urllib.request.urlopen(req, timeout=3) as resp:
            content = resp.read().decode('utf-8', errors='ignore')
            title = 'No Title'
            for line in content.splitlines():
                if '<title>' in line:
                    title = line.strip()
                    break
            # Find nav links
            nav_links = []
            for line in content.splitlines():
                if 'class="btn' in line or "class='btn" in line:
                    nav_links.append(line.strip())
            print(f"{ep} -> HTTP {resp.status} | Title: {title}")
            for nl in nav_links:
                print(f"    {nl}")
    except Exception as e:
        print(f"{ep} -> ERROR: {e}")
"

