using System;
using System.Text;
using System.Runtime.InteropServices;

public class WinFinder {
    public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumProc lpfn, IntPtr lParam);
    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr hWnd);
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);

    public static void Find() {
        EnumWindows(delegate(IntPtr hWnd, IntPtr lParam) {
            if (!IsWindowVisible(hWnd)) return true;
            StringBuilder sb = new StringBuilder(256);
            GetWindowText(hWnd, sb, 256);
            string title = sb.ToString();
            StringBuilder csb = new StringBuilder(128);
            GetClassName(hWnd, csb, 128);
            string cls = csb.ToString();
            if (title.Length > 0 && (title.ToLower().Contains("location") || title.ToLower().Contains("not available") || title.ToLower().Contains("jrfk") || title.ToLower().Contains("disk"))) {
                Console.WriteLine("HWND " + hWnd + " [" + cls + "] " + title);
            }
            return true;
        }, IntPtr.Zero);
    }
}
"@
[WinFinder]::Find()
